<script setup lang="ts">
import {ref,watch,onUnmounted,computed,nextTick} from 'vue';
import {ShieldCheck,Archive,RefreshCw,Trash2,RotateCcw,X} from 'lucide-vue-next';
import {invoke} from '../bridge';
import {trapModalFocus} from '../modalFocus';
import type {Instance,Snapshot,SnapshotReport} from '../../types';
const props=defineProps<{instance:Instance}>();const report=ref<SnapshotReport|null>(null),loading=ref(false),working=ref(false),error=ref(''),message=ref(''),chosen=ref<string[]>([]),keep=ref(10);const restoreTarget=ref<Snapshot|null>(null),restoreName=ref(''),restoreDialog=ref<HTMLElement|null>(null);let restoreFocus:(()=>void)|undefined;let epoch=0,disposed=false;
const selection=computed(()=>report.value?.entries.filter(row=>chosen.value.includes(row.id))||[]),bytes=computed(()=>selection.value.reduce((sum,row)=>sum+row.bytes,0));
function size(bytes:number){return bytes<1024*1024?(bytes/1024).toFixed(0)+' KiB':bytes<1024**3?(bytes/1024**2).toFixed(1)+' MiB':(bytes/1024**3).toFixed(2)+' GiB';}
async function load(){const target=props.instance.id,token=++epoch;loading.value=true;error.value='';try{const value=await invoke<SnapshotReport>('snapshots',{instanceId:target});if(!disposed&&token===epoch){report.value=value;keep.value=value.keep_latest;chosen.value=[];}}catch(e:any){if(token===epoch)error.value=e.message;}finally{if(token===epoch)loading.value=false;}}
async function operation(action:()=>Promise<void>){if(working.value)return;working.value=true;error.value='';message.value='';try{await action();}catch(e:any){error.value=e.message;}finally{working.value=false;}}
function protect(row:Snapshot){void operation(async()=>{await invoke('snapshotPolicy',{instanceId:props.instance.id,revision:report.value!.revision,keepLatest:report.value!.keep_latest,protected:{[row.id]:!row.protected}});await load();message.value='快照保护已更新。';});}
function policy(){void operation(async()=>{await invoke('snapshotPolicy',{instanceId:props.instance.id,revision:report.value!.revision,keepLatest:keep.value,protected:{}});await load();message.value='保留建议已保存，只标记候选，不自动删除。';});}
function backup(){void operation(async()=>{await invoke('backupSnapshot',{instanceId:props.instance.id});message.value='完整备份任务已开始，可在任务中心查看结果。';});}
function clean(){void operation(async()=>{const result=await invoke('cleanupSnapshots',{instanceId:props.instance.id,revision:report.value!.revision,snapshotIds:chosen.value});if(result.cancelled)return;await load();message.value='所选历史快照已清理，当前进度与受保护快照保留。';});}
async function previewRestore(row:Snapshot){if(restoreTarget.value)return;restoreTarget.value=row;restoreName.value=props.instance.name+' · 恢复';await nextTick();if(restoreDialog.value)restoreFocus=trapModalFocus(restoreDialog.value,closeRestore);}
function closeRestore(){if(working.value)return;restoreFocus?.();restoreFocus=undefined;restoreTarget.value=null;}
function restore(){if(!restoreTarget.value)return;const snapshotId=restoreTarget.value.id;void operation(async()=>{const result=await invoke('restoreSnapshot',{instanceId:props.instance.id,snapshotId,revision:report.value!.revision,name:restoreName.value});if(result.cancelled)return;restoreFocus?.();restoreFocus=undefined;restoreTarget.value=null;message.value='恢复任务已开始。源酒馆全部保留，新酒馆保持停止；完成后在首页审阅并重新邀请同伴。';});}
watch([()=>props.instance.id,()=>props.instance.status],()=>void load(),{immediate:true});onUnmounted(()=>{disposed=true;epoch++;restoreFocus?.();});
</script>
<template><section class="panel snapshot-manager"><div class="panel-title"><div><h2><Archive :size="20"/>备份与版本快照</h2><small>{{report?'已统计 '+size(report.bytes)+' · '+report.entries.length+' 项':'读取本机保留的进度'}}</small></div><div class="row"><button class="text-button" :disabled="loading||working" @click="load"><RefreshCw :size="15"/>刷新快照</button><button class="secondary" :disabled="!instance.commit||instance.status==='busy'||working" @click="backup">创建完整备份</button></div></div>
 <p class="help-text">完整备份保存数据库、素材与已安装模块；版本快照用于版本回退。二者均可能含私人内容，不自动上传。最新备份与各版本当前快照始终保留。</p><p v-if="error||report?.error" class="warning" role="alert">{{error||report?.error}}</p><p v-if="message" class="help-text" role="status">{{message}}</p><p v-if="loading" class="help-text" role="status">正在读取快照与占用…</p>
 <template v-if="report"><div class="snapshot-policy"><label>历史保留建议<select v-model.number="keep" :disabled="working||report.read_only" aria-label="快照保留数量"><option v-for="count in [1,5,10,20,50,100]" :key="count" :value="count">最近 {{count}} 项</option></select></label><button class="text-button" :disabled="working||report.read_only||instance.status==='busy'" @click="policy">保存建议</button><small class="muted">只标记清理候选，仍需明确选择与确认。</small></div><div v-if="!report.entries.length" class="empty"><Archive :size="28"/><h3>还没有保留的快照</h3><p>本体版本切换会自动备份；也可创建一份新的完整备份。</p></div><article v-for="row in report.entries" :key="row.id" class="snapshot-row"><input v-model="chosen" type="checkbox" :value="row.id" :disabled="!row.can_delete||working||report.read_only" :aria-label="'选择历史快照 '+row.name"/><div><b>{{row.kind==='backup'?'完整备份':'版本 '+(row.version||'待检查')}} <span v-if="row.protected" class="badge"><ShieldCheck :size="12"/>{{row.system_protected?'系统保留':'已保护'}}</span><span v-if="row.in_use" class="badge">任务使用中</span><span v-if="row.candidate" class="badge">清理候选</span></b><small>{{row.created_at}} · {{size(row.bytes)}}</small><code>{{row.name}}</code><p v-if="row.warning" class="warning">{{row.warning}}</p></div><button v-if="row.kind==='backup'" class="text-button" :disabled="!!row.warning||row.in_use||working||instance.status==='running'||instance.status==='busy'" @click="previewRestore(row)"><RotateCcw :size="14"/>恢复为新酒馆</button><button class="text-button" :disabled="row.system_protected||row.in_use||working||report.read_only" @click="protect(row)">{{row.protected?'解除保护':'保护此快照'}}</button></article><p v-if="instance.status==='running'||instance.status==='busy'" class="help-text">停止酒馆并等待任务结束后才能清理；当前游戏进度不会在此处删除。</p><div class="row"><button class="secondary" :disabled="!chosen.length||working||report.read_only" @click="clean"><Trash2 :size="15"/>清理所选 {{chosen.length}} 项 · {{size(bytes)}}</button></div></template>
</section><Teleport to="body"><div v-if="restoreTarget" class="overlay"><section ref="restoreDialog" class="dialog" role="dialog" aria-modal="true" aria-label="恢复完整备份"><button class="dialog-close" aria-label="关闭恢复预览" :disabled="working" @click="closeRestore"><X :size="20"/></button><span class="eyebrow">KEEP BOTH TIMELINES</span><h2>从备份恢复新的酒馆</h2><p>{{restoreTarget.created_at}} · {{size(restoreTarget.bytes)}}<code class="content-hash">{{restoreTarget.name}}</code></p><label class="form">新酒馆名称<input v-model="restoreName" maxlength="48" aria-label="恢复的新酒馆名称" :disabled="working"/></label><p class="help-text">源酒馆的当前进度和原备份全部保留。恢复的数据库、素材与模块进入新目录，使用源酒馆当前本体并预检；完成后保持停止。</p><p class="help-text">房主保留当前身份；玩家访问、旧会话、分配、邀请与社区模块授权关闭，启动前重新审阅并邀请同伴。房间内容锁保留，API 档案不自动复制。</p><p v-if="error" class="warning" role="alert">{{error}}</p><div class="row"><button class="secondary" :disabled="working" @click="closeRestore">取消</button><button class="primary" :disabled="working||!restoreName.trim()" @click="restore">{{working?'准备恢复…':'继续确认恢复范围'}}</button></div></section></div></Teleport></template>
